func PlayAnimation() {
	var esc = "\x1b"
	ticker := time.NewTicker(100 * time.Millisecond)
	for i := 0; i < len(frames); i++ {
		if i > 0 {
			// Move the cursor 20 lines up
			fmt.Printf(esc+"[%dA", 20)
		}
		coreutils.PrintMessage(frames[i])
		<-ticker.C
	}

	ticker.Stop()
	time.Sleep(3 * time.Second)
	fmt.Printf(esc+"[%dA", 20)
	// Clear characters from cursor to end of screen
	fmt.Printf(esc + "[0J")
}
